import{_ as o,a0 as p,w as s,s as a,ao as u,I as n,x as e,a1 as r,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"MultiWriter：同时将 ISO 镜像并发写入 20 个  USB 启动盘 | LCTT x X-CMD","titleTemplate":false,"description":"MultiWriter：同时将 ISO 镜像并发写入 20 个  USB 启动盘 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"MultiWriter：同时将 ISO 镜像并发写入 20 个  USB 启动盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"MultiWriter：同时将 ISO 镜像并发写入 20 个  USB 启动盘 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150106 This App Can Write a Single ISO to 20 USB Drives Simultaneously","title":"MultiWriter：同时将 ISO 镜像并发写入 20 个  USB 启动盘","tag":"201503","desc":""},"relativePath":"201503/20150106 This App Can Write a Single ISO to 20 USB Drives Simultaneously.md","filePath":"[post].md"}'),m={name:"201503/20150106 This App Can Write a Single ISO to 20 USB Drives Simultaneously.md"};function S(g,t,d,T,b,f){const i=p("Link");return s(),a("div",null,[t[17]||(t[17]=u('<h1 id="multiwriter-同时将-iso-镜像并发写入-20-个-usb-启动盘" tabindex="-1">MultiWriter：同时将 ISO 镜像并发写入 20 个 USB 启动盘 <a class="header-anchor" href="#multiwriter-同时将-iso-镜像并发写入-20-个-usb-启动盘" aria-label="Permalink to “MultiWriter：同时将 ISO 镜像并发写入 20 个  USB 启动盘”">​</a></h1><p><strong>我的问题是如何把一个Linux ISO 文件烧录到 17 个 USB 启动盘？</strong></p><p>精通代码的人会写一个 bash 脚本来自动化处理，而大部分的人会使用像 USB 启动盘创建器这样的图形用户界面工具来把 ISO 文件一个、一个的烧录到驱动盘中。但剩下的还有一些人也许会很快得出结论，两种方法都不太理想。</p><h3 id="问题-解决" tabindex="-1">问题 &gt; 解决 <a class="header-anchor" href="#问题-解决" aria-label="Permalink to “问题 &gt; 解决”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/01/gnome-multi-writer.jpg" alt="GNOME MultiWriter in action"></p><p><em>GNOME MultiWriter 在运行当中</em></p><p>Richard Hughes，一个 GNOME 开发者，也面临着类似的困境。他要创建一批预装操作系统的 USB 启动盘，需要一个足够简单的工具，使得像他父亲这样的用户也能使用。</p><p>他的反应是开发<strong>品牌性的新应用程序</strong>，使上面的两种方法合二为一，创造出易用的一款工具。</p>',8)),n("p",null,[t[1]||(t[1]=e("它的名字就叫 “",-1)),r(i,{href:"https://github.com/hughsie/gnome-multi-writer/"},{default:l(()=>[...t[0]||(t[0]=[e("GNOME MultiWriter",-1)])]),_:1}),t[2]||(t[2]=e("”，可以同时把单个的 ISO 或 IMG 文件写入多个 USB 驱动盘。",-1))]),t[18]||(t[18]=u(`<p>它不支持个性化自定义或命令行执行的功能，使用它就可以省掉浪费一下午的时间来对相同的操作的重复动作。</p><p>您需要的就是这一款应用程序、一个 ISO 镜像文件、一些拇指驱动盘以用许多空 USB 接口。</p><h3 id="用例和安装" tabindex="-1">用例和安装 <a class="header-anchor" href="#用例和安装" aria-label="Permalink to “用例和安装”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/01/mutli-writer-on-ubuntu.jpg" alt="The app can be installed on Ubuntu"></p><p><em>该应用程序可以在 Ubuntu 上安装</em></p><p>这款应用程序的定义使用场景很不错，正适合使用于预装正要发布的操作系统或 live 映像的 USB 启动盘上。</p><p>那就是说，任何人想要创建一个单独可启动的 USB 启动盘的话，也是一样的适用 - 因我用 Ubuntu 的内置磁盘创建工具来创建可引导的映像从来没有一次成功过的，所以这方案对我来说是个好消息！</p><p>它的开发者 Hughes 说它<strong>最高能支持20个 USB 启动盘</strong>，每个盘的大小在 1GB 到 32GB之间。</p><p>GNOME MultiWriter 也有不好的地方（到现在为止）就是它还没有一个完结、稳定的成品。它是能工作，但在早期的时候，还没有可安装的二进制版本或可添加到你庞大软件源的 PPA。</p><p>如果您知道通常的 configure/make 的操作流程的话，可以获取其源码并随时都可以编译运行。在 Ubuntu14.10 系统上，你可能还需要首先安装以下软件包：</p><pre><code>sudo apt-get install gnome-common yelp-tools libcanberra-gtk3-dev libudisks2-dev gobject-introspection
</code></pre><p>如果您可以运行起来，已经玩转的话，给我们分享下您的感受！</p><p>此项目托管在 GitHub 上，盼望对其提出问题缺陷和发起 pull 请求，在上面也可以找到压缩包下载，进行手动安装。</p>`,13)),n("ul",null,[n("li",null,[r(i,{href:"https://github.com/hughsie/gnome-multi-writer/"},{default:l(()=>[...t[3]||(t[3]=[e("Github 上的 GNOME MultiWriter",-1)])]),_:1})])]),t[19]||(t[19]=n("hr",null,null,-1)),n("p",null,[t[5]||(t[5]=e("via: ",-1)),r(i,{href:"http://www.omgubuntu.co.uk/2015/01/gnome-multiwriter-iso-usb-utility"},{default:l(()=>[...t[4]||(t[4]=[e("http://www.omgubuntu.co.uk/2015/01/gnome-multiwriter-iso-usb-utility",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=e("作者：",-1)),r(i,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:l(()=>[...t[6]||(t[6]=[e("Joey-Elijah Sneddon",-1)])]),_:1}),t[10]||(t[10]=e(" 译者：",-1)),r(i,{href:"https://github.com/runningwater"},{default:l(()=>[...t[7]||(t[7]=[e("runningwater",-1)])]),_:1}),t[11]||(t[11]=e(" 校对：",-1)),r(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=e("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原创翻译，",-1)),r(i,{href:"http://linux.cn/"},{default:l(()=>[...t[13]||(t[13]=[e("Linux中国",-1)])]),_:1}),t[16]||(t[16]=e(" 荣誉推出",-1))])])}const U=o(m,[["render",S]]);export{M as __pageData,U as default};
